"""Six-month, outcome-based AI Engineering curriculum.
Weights are relative priorities (1 = light, 5 = core). Each topic has concrete completion checks.
"""
MONTHS = [
    {"number": 1, "name": "Engineering foundations", "outcome": "Build reliable backend services and write maintainable Python.", "deliverables": ["FastAPI service", "PostgreSQL schema", "tests and API docs"]},
    {"number": 2, "name": "ML/DL essentials + LLM engineering", "outcome": "Understand practical model behavior and build robust LLM-backed features.", "deliverables": ["ML evaluation notebook", "LLM service", "tool calling"]},
    {"number": 3, "name": "RAG engineering", "outcome": "Build and measure a retrieval system rather than just connecting a vector database.", "deliverables": ["ingestion pipeline", "retrieval API", "evaluation set"]},
    {"number": 4, "name": "Agentic AI and workflows", "outcome": "Build bounded, observable workflows with tools, state and human approval.", "deliverables": ["workflow graph", "persistence", "failure handling"]},
    {"number": 5, "name": "Cloud, production AI and system design", "outcome": "Deploy, secure, observe and reason about system behavior under load.", "deliverables": ["Docker deployment", "monitoring", "system design diagrams"]},
    {"number": 6, "name": "Architecture and interviews", "outcome": "Explain design decisions, trade-offs and production behavior confidently.", "deliverables": ["architecture case studies", "interview revision", "portfolio polish"]},
]

def T(id, month, title, weight, why, example, *tasks):
    return {"id": id, "month": month, "title": title, "weight": weight, "why": why, "example": example, "tasks": list(tasks)}

